import type { Coach } from "./mockCoaches";
import { mockCoaches } from "./mockCoaches";

type LessonTypeId = "private" | "group";

type BookingLessonType = {
  id: LessonTypeId;
  label: string;
  price: string;
  unit: string;
  description: string;
  duration: string;
  tagline: string;
  bullets: string[];
};

export type GroupParticipant = {
  id: string;
  name: string;
  skillLevel?: string;
  focusArea?: string;
  avatarUrl?: string;
  joinedLabel?: string;
};

type BookingSlot = {
  id: string;
  time: string;
  lessonType: LessonTypeId;
  duration: string;
  price: string;
  spotsRemaining: number;
  title?: string;
  participants?: GroupParticipant[];
  location?: string;
};

type BookingDate = {
  id: string;
  day: string;
  date: string;
  label: string;
  totalSlots: number;
  slots: BookingSlot[];
};

type HighlightChipIcon = "users" | "trophy" | "spark";

type HighlightChip = {
  icon: HighlightChipIcon;
  label: string;
};

type MetricIcon = "dollar" | "users" | "clock" | "map";

type Metric = {
  icon: MetricIcon;
  label: string;
  value: string;
  caption?: string;
};

type LessonDetail = {
  title: string;
  description: string;
  price: string;
  cadence: string;
};

type LessonPackage = {
  lessonTypeId: LessonTypeId;
  id: string;
  title: string;
  lessons: number;
  discount: string;
  description: string;
  totalPrice: string;
  pricePerLesson: string;
};

type PlayerLessonCredit = {
  lessonTypeId: LessonTypeId;
  lessonTypeLabel: string;
  remaining: number;
  totalPurchased?: number;
  upcomingExpiryLabel?: string;
  lastPurchasedLabel?: string;
};

export type CoachProfile = Coach & {
  about: string;
  headlineBadge?: string;
  highlightChips: HighlightChip[];
  metrics: Metric[];
  certifications: string[];
  specialties: string[];
  coachingLocations: string[];
  lessonDetails: LessonDetail[];
  lessonPackages: LessonPackage[];
  playerLessonCredits?: PlayerLessonCredit[];
  booking: {
    headline: string;
    lessonTypes: BookingLessonType[];
    defaultLessonType: LessonTypeId;
    monthLabel: string;
    availableDates: BookingDate[];
    note: string;
  };
};

