export const findCoachProfile = (id: string | number) => {
  const numericId = typeof id === "number" ? id : Number(id);
  if (Number.isNaN(numericId)) {
    return undefined;
  }
  return mockCoachProfiles.find((profile) => profile.id === numericId);
};
